package io.github.ningpp.compat;

/**
 * Replacement for System.Runtime.Serialization.FormatterConverter (generated by
 * CSharpToJava converter). Used as the converter argument when constructing a
 * SerializationInfo stand-in.
 */
public final class FormatterConverter {

    public FormatterConverter() {
    }

    public Object convert(Object value, Class<?> type) {
        if (value == null) {
            return null;
        }
        if (type == null || type.isInstance(value)) {
            return value;
        }
        return Convert.changeType(value, type);
    }

    public boolean toBoolean(Object value) {
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        if (value == null) {
            throw new ArgumentNullException("value");
        }
        return Boolean.parseBoolean(value.toString());
    }

    public int toInt32(Object value) {
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        if (value == null) {
            throw new ArgumentNullException("value");
        }
        return Integer.parseInt(value.toString());
    }

    public long toInt64(Object value) {
        if (value instanceof Number) {
            return ((Number) value).longValue();
        }
        if (value == null) {
            throw new ArgumentNullException("value");
        }
        return Long.parseLong(value.toString());
    }

    public String toString(Object value) {
        return value == null ? null : value.toString();
    }
}
